-- REVIEW-ROTATE-1 + IL-SUPERSEDED-1 + CF-OBS-NESTED-AGE-1 (2026-10-19, qnfo-fleet-control 0.34.0, pillar autonomy).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-goal-review-empty-reply', 'fm-relapse-for-superseded-metric', 'fm-cf-obs-nested-pin-stale'); DELETE FROM failure_modes WHERE fm_key IN ('goal-review-empty-reply', 'relapse-for-superseded-metric', 'cf-obs-nested-pin-stale'); DELETE FROM control_registry WHERE control IN ('improvement-loop-superseded-marker', 'cf-obs-nested-too-deep-pin');
--
-- Three defects found by the 2026-10-19 audit, fixed in qnfo-fleet-control 0.34.0; this file records their failure modes with
-- standing detectors and registers the one filter the change adds (DOCTRINE-1: a filter on a detector needs a control_registry
-- row) and the one pin it bounds.
--   goal-review-empty-reply     cmGoalReview re-ran the SAME reviewer on all three tries (deepseek-v4-flash-0731 answered empty on
--                               22 of 26 unreadable replies in 24 h; gpt-oss-120b read the same diffs first try), so the goal-review
--                               safety layer dropped out ("the checks decide"). Now each try rotates to the next eligible reviewer.
--   relapse-for-superseded-metric  IMPROVEMENT-LOOP-1 judged relapse of closed METRIC-TRIGGER issues for metrics SLA-120M-2 / -6
--                               superseded on purpose (issues_open_over_24h, open_issues_without_doer_24h), filing METRIC-FIX-RELAPSED-1
--                               2617 and 2618. Now the registry target marker "[superseded by <metric>" removes the metric from
--                               regression and relapse judgement and the loop closes the open findings with "superseded by" evidence.
--   cf-obs-nested-pin-stale     cfObsClassify returned "active" for "triggers nested too deep" at any age, so those Cloudflare groups
--                               never reached the 72 h stale-resolve branch and their fleet_issue_dispatch rows stayed tracked.
--
-- The detectors are standing probes (d1-query, hourly) with windows of at most 120 minutes (SLA-120M).
-- spof-review: detectors only (no trigger). The second path for each is the loop that owns the fix (qnfo-fleet-control code-merge
-- tick, improvementLoopTick, pollObservability) re-running every tick.

INSERT OR REPLACE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id) VALUES
 ('improvement-loop-superseded-marker', 'qnfo-fleet-control improvementEvaluate (IL-SUPERSEDED-1, 0.34.0): metric_registry.target containing "[superseded by <metric>" with the successor in the registry', 'filter',
  'IMPROVEMENT-LOOP-1 filing METRIC-FIX-RELAPSED-1 / METRIC-REGRESSION-1 for a metric that SLA-120M-2 / -6 replaced on purpose (issues 2617 and 2618, refiled every hour for as long as the old window stayed off target)',
  0, 'keep', 'applied',
  'the successor metric carries its own enabled trigger (METRIC-TRIGGER-5937 issues_open_over_120m, METRIC-TRIGGER-5944 open_issues_without_doer_120m) and is still judged by the loop; the superseded metric stays measured in metric_history. Only the explicit marker disqualifies: 16 other registry metrics have every trigger disabled for other reasons and keep their regression and relapse checks.',
  NULL,
  'qnfo-fleet-control/improvement-superseded.test.mjs: 10 of 19 assertions pass and 9 fail on 0.33.19 (a superseded metric files a relapse, its open issue stays open); all 19 pass on 0.34.0, including the controls (no marker, or a marker whose successor is not in the registry, still files; a metric with disabled triggers and no marker keeps its open relapse issue).',
  2617),
 ('cf-obs-nested-too-deep-pin', 'qnfo-fleet-control cfObsClassify (CF-OBS-SWEEP-1): group titles containing "triggers nested too deep" classified active', 'filter',
  'a Cloudflare Observability group for the closed trigger-depth fault (issues 2785, 2794, 2817) being auto-resolved while the root cause was open',
  0, 'demote', 'applied',
  'the rule now holds only while the group was seen inside CF_OBS_STALE_H (72 h), like its sibling rules; a recurrence re-activates the group in Cloudflare and the CF-OBS bridge files it again. fm-trigger-depth-compile passes in remediation_verifications (the fault is fixed).',
  NULL,
  'qnfo-fleet-control/cf-obs-classify.test.mjs: 7 of 10 assertions pass and 3 fail on 0.33.19 (a group quiet 80 h, 30 days or with no lastObserved stayed active); all 10 pass on 0.34.0.',
  NULL);

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, trigger_condition, symptom, blast_radius) VALUES
 ('goal-review-empty-reply', 'the code-merge goal review gets no readable verdict from its reviewer on all three tries and the checks decide alone', 'cmGoalReview re-ran the same reviewer model on every try, and the first reviewer for an openai proposer (deepseek-v4-flash-0731, a reasoning model) answers with an empty content on large diffs; 21 of 37 deepseek reviews and 4 of 19 gpt-oss reviews were unreadable between 2026-10-17 and 2026-10-19', 'qnfo-fleet-control 0.34.0 REVIEW-ROTATE-1: each try rotates to the next eligible reviewer outside the proposer family, reads reasoning_content when the model ended on its own, raises the budget, asks for reasoning_effort low on a retry where the model accepts it, and records finish_reason, completion_tokens and the models tried on the event row', 'remediation_contracts fm-goal-review-empty-reply (d1-query, hourly)', 'fm-goal-review-empty-reply', '2026-10-19', 'a reviewer model returns an empty or truncated reply on a large diff', 'cloud_ops_events code-merge.goal-review text "goal review unavailable after 3 tries; the checks decide"; cf-obs group fleet-control:cmReviewParse:no-verdict', 'every code-loop pull request merged without the goal-review layer'),
 ('relapse-for-superseded-metric', 'a metric replaced by a successor keeps an open METRIC-FIX-RELAPSED-1 or METRIC-REGRESSION-1 issue', 'improvementEvaluate judged any closed METRIC-TRIGGER issue against metric_history with no knowledge that the metric was superseded on purpose; the old window stays measured and off target, so the finding was filed and refiled', 'qnfo-fleet-control 0.34.0 IL-SUPERSEDED-1: the registry target marker "[superseded by <metric>" (successor in the registry) removes the metric from judgement and the loop closes its open findings with superseded-by evidence', 'remediation_contracts fm-relapse-for-superseded-metric (d1-query, hourly)', 'fm-relapse-for-superseded-metric', '2026-10-19', 'a trigger is superseded by a new metric (SLA-120M-n) and the old metric stays in metric_registry', 'agent_issues 2617 and 2618 METRIC-FIX-RELAPSED-1 for issues_open_over_24h and open_issues_without_doer_24h', 'the open-issue count and the improvement loop findings'),
 ('cf-obs-nested-pin-stale', 'a Cloudflare Observability group for a fixed fault stays active and tracked forever', 'cfObsClassify returned active for "triggers nested too deep" with no age bound, so the group never reached the CF_OBS_STALE_H stale-resolve branch', 'qnfo-fleet-control 0.34.0 CF-OBS-NESTED-AGE-1: the rule has the same age bound as its siblings; pollObservability resolves the group and its dispatch row once it has been quiet for 72 h', 'remediation_contracts fm-cf-obs-nested-pin-stale (d1-query, hourly)', 'fm-cf-obs-nested-pin-stale', '2026-10-19', 'a fault is fixed but its Cloudflare group title is pinned by a classifier rule', '24 fleet_issue_dispatch rows tracked for nested-too-deep groups last seen 2026-10-18 or earlier', 'the dispatch queue and the GitHub mirror issues for those groups');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module) VALUES
 ('fm-goal-review-empty-reply', NULL, 'a goal-review event whose three tries were all unreadable in the last 120 minutes', 'qnfo-fleet-control code-merge tick rotates the reviewer on each try (REVIEW-ROTATE-1); a hit here means every eligible reviewer returned an unreadable reply, so read the event meta (finish, completion_tokens, models)', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''code-merge.goal-review'' AND ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-120 minutes'') AND text LIKE ''%goal review unavailable after%'') AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode'),
 ('fm-relapse-for-superseded-metric', NULL, 'an open METRIC-FIX-RELAPSED-1 or METRIC-REGRESSION-1 issue whose metric registry target carries the superseded marker', 'improvementLoopTick closes it with superseded-by evidence on its next hourly run (IL-SUPERSEDED-1)', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues a JOIN metric_registry m ON m.metric = substr(a.title, instr(a.title, '': '') + 2) WHERE a.status = ''open'' AND (a.title LIKE ''METRIC-FIX-RELAPSED-1: %'' OR a.title LIKE ''METRIC-REGRESSION-1: %'') AND m.target LIKE ''%[superseded by %'') AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode'),
 ('fm-cf-obs-nested-pin-stale', NULL, 'a nested-too-deep Cloudflare group last observed more than 74 hours ago that is not resolved in fleet_issue_dispatch', 'pollObservability classifies it resolved (CF-OBS-NESTED-AGE-1) and PATCHes it on its next */10 run', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM fleet_issue_dispatch d WHERE d.category = ''worker-observability'' AND d.state <> ''resolved'' AND json_valid(d.payload) AND lower(d.payload) LIKE ''%triggers nested too deep%'' AND CAST(json_extract(d.payload, ''$.lastObserved'') AS INTEGER) < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 74 * 3600) * 1000) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode');
